#!/usr/bin/env npx tsx
// Vincent: this experimental code was, in part, generated by Deepseek
// This script queries the SiteHits metric for a Static Web App and writes results to site_hits.txt
// Run with: npx tsx site_hits.ts

import "dotenv/config";
import { writeFileSync, appendFileSync } from "fs";

const outputFile = "site_hits.txt";
writeFileSync(outputFile, "");

function log(line: string): void {
    appendFileSync(outputFile, line + "\n");
}

// Note: different env vars than the similar, other ts scripts
const directoryId = process.env["directory_id"];
const appRegistrationId = process.env["app_registration_id"];
const secretValue = process.env["secret_value"];
const staticWebAppResourceId = process.env["static_web_app_resource_id"];

// NOTE: different scope than the Log Analytics script — metrics live behind A
const tokenResponse = await fetch(
    `https://login.microsoftonline.com/${directoryId}/oauth2/v2.0/token`,
    {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
            client_id: appRegistrationId!,
            client_secret: secretValue!,
            grant_type: "client_credentials",
            scope: "https://management.azure.com/.default"
        })
    }
);

const { access_token: token } = await tokenResponse.json();

interface MetricValue {
    timeStamp: string;
    total?: number;
}

interface TimeSeries {
    metadatavalues?: unknown[];
    data: MetricValue[];
}

interface Metric {
    id: string;
    name: { value: string; localizedValue: string };
    timeseries: TimeSeries[];
    unit: string;
}

interface MetricsResponse {
    value: Metric[];
    // cost, interval, namespace, resourceregion, timespan also present
    [key: string]: unknown;
}

async function getMetric(
    label: string,
    metricNames: string[],
    opts: {
        startTime: string;   // ISO 8601, e.g. new Date(Date.now() - 86_400_000).toISOString()
        endTime: string;     // ISO 8601
        interval?: string;   // ISO 8601 duration, e.g. "PT1H", "PT5M", default "PT1H"
        aggregation?: string; // "Total" | "Average" | "Maximum" | "Minimum" | "Count"
    }
): Promise<void> {
    const params = new URLSearchParams({
        metricnames: metricNames.join(","),
        timespan: `${opts.startTime}/${opts.endTime}`,
        interval: opts.interval ?? "PT1H",
        aggregation: opts.aggregation ?? "Total",
        "api-version": "2019-07-01"
    });

    const url =
        `https://management.azure.com${staticWebAppResourceId}/providers/microsoft.insights/metrics?` +
        params.toString();

    const result = await fetch(url, {
        method: "GET",
        headers: { Authorization: `Bearer ${token}` }
    });

    const body = (await result.json()) as MetricsResponse;

    log(`\n===** ${label} **===`);
    log(JSON.stringify(body, null, 2));

    // Also emit a compact, one-line-per-point CSV-ish view for easy diffing.
    for (const metric of body.value ?? []) {
        for (const series of metric.timeseries ?? []) {
            for (const point of series.data ?? []) {
                const value =
                    point.total ??
                    (point as Record<string, unknown>)["average"] ??
                    (point as Record<string, unknown>)["maximum"] ??
                    (point as Record<string, unknown>)["minimum"] ??
                    (point as Record<string, unknown>)["count"];
                log(`${metric.name.value}\t${point.timeStamp}\t${value}`);
            }
        }
    }
}

async function listMetricDefinitions(): Promise<void> {
    const url =
        `https://management.azure.com${staticWebAppResourceId}/providers/microsoft.insights/metricDefinitions` +
        `?api-version=2018-01-01`;

    const result = await fetch(url, {
        method: "GET",
        headers: { Authorization: `Bearer ${token}` }
    });

    const body = await result.json();
    log(`\n===** Available metric definitions **===`);
    log(JSON.stringify(body, null, 2));
}


// --- Example calls -------------------------------------------------------

const endTime = new Date().toISOString();
const day = 24 * 60 * 60 * 1000
const startTime = new Date(Date.now() - day * 365).toISOString();

// Discover which metrics the SWA emits (handy the first time you run this)
await listMetricDefinitions();

// The one you actually wanted
await getMetric("SiteHits (last 24h, hourly, Total)", ["SiteHits"], {
    startTime,
    endTime,
    interval: "PT1H",
    aggregation: "Total"
});
